int R = 3;
int **display = new int*[R]; // Array of Pointers (Dope Vector)

// Dynamic, potentially ragged allocation
display[0] = new int[5];  // Row 0 (size 5)
display[1] = new int[2];  // Row 1 (size 2)
display[2] = new int[8];  // Row 2 (size 8)

display[1][0] = 42;       // Access: display[Row][Col]

// Cleanup (must free rows first)
for (int i = 0; i < R; ++i) {
    delete[] display[i];
}
delete[] display;
display = nullptr;
